CREATE OR REPLACE FUNCTION public.set_order_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  next_number integer;
BEGIN
  PERFORM 1 FROM public.store_config WHERE id = NEW.store_id FOR UPDATE;
  SELECT COALESCE(MAX(order_number), 0) + 1
  INTO next_number
  FROM public.orders
  WHERE store_id = NEW.store_id;
  NEW.order_number := next_number;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_coupons_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$
